:root {
  --bg-ticket: #1e1433;
  --bg-header: #2d1f4e;
  --bg-card: #3b2a6b;
  --bg-footer: #150e26;
  --accent-gold: #c9a84c;
  --accent-lavender: #a78bca;
  --accent-rose: #e07fa0;
  --text-primary: #f0e8ff;
  --text-muted: #9b86b8;
  --text-dark: #1e1433;
  --border-subtle: #4a3575;
}

.tarot-ticket {
  width: 460px;
  background-color: var(--bg-ticket);
  border-radius: 14px;
  border: 2px solid var(--accent-gold);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  font-size: 13px;
}

.ticket-header {
  background-color: var(--bg-header);
  text-align: center;
  padding: 10px 16px 8px;
  border-bottom: 1px solid var(--border-subtle);
  display: flex;
  flex-direction: column;
  gap: 1px;
}

.ticket-eyebrow {
  font-size: 10px;
  letter-spacing: 0.15em;
  color: var(--accent-gold);
  font-weight: 600;
  text-transform: uppercase;
}

.ticket-title {
  font-size: 20px;
  font-weight: 800;
  color: var(--text-primary);
  margin: 0;
  line-height: 1.1;
}

.ticket-subtitle {
  font-size: 11px;
  color: var(--accent-lavender);
  letter-spacing: 0.08em;
}

.ticket-body {
  display: flex;
  flex-direction: row;
  flex: 1;
}

.spread-info {
  flex: 1;
  padding: 12px 16px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  border-right: 1px dashed var(--border-subtle);
}

.info-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-bottom: 7px;
  border-bottom: 1px solid var(--border-subtle);
}

.info-row:last-child {
  border-bottom: none;
  padding-bottom: 0;
}

.info-label {
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--text-muted);
  font-weight: 600;
}

.info-value {
  font-size: 12px;
  font-weight: 700;
  color: var(--text-primary);
}

.card-drawn {
  width: 148px;
  padding: 10px 12px 8px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
}

.drawn-label {
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--text-muted);
  font-weight: 600;
  margin: 0;
}

.tarot-card {
  background-color: var(--bg-card);
  border: 2px solid var(--accent-gold);
  border-radius: 8px;
  width: 72px;
  padding: 6px 4px 4px;
  text-align: center;
  margin: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 1px;
}

.card-roman {
  font-size: 9px;
  font-weight: 700;
  color: var(--accent-gold);
  letter-spacing: 0.05em;
}

.card-icon {
  font-size: 22px;
  line-height: 1.1;
}

.card-name {
  font-size: 9px;
  font-weight: 700;
  color: var(--text-primary);
  margin: 1px 0 0;
  letter-spacing: 0.04em;
}

.card-keywords {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 3px;
  width: 100%;
}

.card-keywords li {
  font-size: 10px;
  font-weight: 600;
  color: var(--accent-rose);
  text-align: center;
  background-color: var(--bg-header);
  border-radius: 20px;
  padding: 2px 6px;
}

.ticket-footer {
  background-color: var(--bg-footer);
  border-top: 1px dashed var(--border-subtle);
  padding: 7px 16px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.ticket-code {
  font-size: 10px;
  font-weight: 700;
  color: var(--text-muted);
  letter-spacing: 0.1em;
}

.ticket-perforated {
  flex: 1;
  height: 1px;
  border-top: 2px dashed var(--border-subtle);
}

.ticket-admit {
  font-size: 10px;
  font-weight: 800;
  color: var(--accent-gold);
  letter-spacing: 0.15em;
  text-transform: uppercase;
  border: 1px solid var(--accent-gold);
  border-radius: 4px;
  padding: 2px 7px;
}
